	    Metric entity = new Metric();
            entity.setMetricId( event.getMetricId() );
            entity.setName( event.getName() );
            entity.setExpression( event.getExpression() );
            entity.setUnit( event.getUnit() );
            entity.setMetricType( event.getMetricType() );
	    
    	// ------------------------------------------
