    /**
     * Method to retrieve the Metric via an MetricPrimaryKey.
     * @param 	id Long
     * @return 	Metric
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Metric handle( FindMetricQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getMetricId() );
    }
    
    /**
     * Method to retrieve a collection of all Metrics
     *
     * @param	query	FindAllMetricQuery 
     * @return 	List<Metric> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Metric> handle( FindAllMetricQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindMetric,
 * but only if the id matches
 *
 * @param		entity	Metric
 */
	protected void emitFindMetric( Metric entity ) {
		LOGGER.info("handling emitFindMetric" );
		
	    queryUpdateEmitter.emit(FindMetricQuery.class,
	                            query -> query.getFilter().getMetricId().equals(entity.getMetricId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllMetric
	 * 
	 * @param		entity	Metric
	 */
	protected void emitFindAllMetric( Metric entity ) {
		LOGGER.info("handling emitFindAllMetric" );
		
	    queryUpdateEmitter.emit(FindAllMetricQuery.class,
	                            query -> true,
	                            entity);
	}

